      double thisMaxX = thisShape.getMaxX();
      double thisMinY = thisShape.getMinY();
      double thisMaxY = thisShape.getMaxY();
      double otherMinX = otherShape.getMinX();
      double otherMaxX = otherShape.getMaxX();
      double otherMinY = otherShape.getMinY();
      double otherMaxY = otherShape.getMaxY();
      double thisCenterX = (thisMinX + thisMaxX) * 0.5d;
      double thisCenterY = (thisMinY + thisMaxY) * 0.5d;
