            probeY = (float) thisMinY;
            if (thisX > 1.0f) {
              probeX = XYEncodingUtils.decode(XYEncodingUtils.encode(thisX));
              if (thisY < -1.0f) {
                probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
              }
            }
          } else {
            if (thisX > 1.0f) {
              probeX = XYEncodingUtils.decode(XYEncodingUtils.encode(thisX));
            }
          }
        } else if (thisX < 0.0f) {
          probeX = (float) thisMinX;
          if (thisY > 0.0f) {
            probeY = (float) thisMaxY;
            if (thisX < -1.0f) {
              probeX = XYEncodingUtils.decode(XYEncodingUtils.encode(thisX));
              if (thisY > 1.0f) {
                probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
              }
            }
          } else if (thisY < 0.0f) {
            probeY = (float) thisMinY;
            if (thisX < -1.0f) {
              probeX = XYEncodingUtils.decode(XYEncodingUtils.encode(thisX));
              if (thisY < -1.0f) {
                probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
              }
            }
          } else {
            if (thisX < -1.0f) {
              probeX = XYEncodingUtils.decode(XYEncodingUtils.encode(thisX));
            }
          }
        } else {
          if (thisY > 0.0f) {
            probeY = (float) thisMaxY;
            if (thisY > 1.0f) {
