            if (thisY < -1.0f) {
              probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
            }
          }
        }
        boolean probeOk = thisShape.contains(probeX, probeY);
        return probeOk && point.x == x && point.y == y;
      }
      return false;
    }
    return false;
  }

  @Override
  public int hashCode() {
    int result = Float.hashCode(x);
    result = 31 * result + Float.hashCode(y);
    return result;
  }

  @Override
  public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append("Point(");
    sb.append(x);
    sb.append(",");
    sb.append(y);
    sb.append(')');
    return sb.toString();
  }
}

